/**
 * PreToolUse hook for Write/Edit: Protect important files.
 *
 * Two tiers:
 *   BLOCK (exit 2) — generated files that commands manage (AGENT.md, INIT.md)
 *   WARN  (exit 0) — user-owned files that may need updates but deserve a heads-up
 *
 * Repos can extend the warn list via "protected_files" in mod.config.json.
 */

const fs = require("fs");
const path = require("path");

// Generated by /init — edits should go through commands, not direct editing
const BLOCK_FILES = ["AGENT.md", "docs/AGENT.md", "INIT.md"];

// User-owned but important — warn, don't block
const WARN_FILES = [
  "mod.config.json",
  "README.md",
  "README_zh.md",
  "CHANGELOG.md",
  "CHANGELOG_zh.md",
];

/**
 * Try to read repo-specific protected files from mod.config.json in CWD.
 * Returns an empty array on any failure (missing file, parse error, etc.).
 */
function readRepoProtectedFiles() {
  try {
    const configPath = path.join(process.cwd(), "mod.config.json");
    const raw = fs.readFileSync(configPath, "utf8");
    const config = JSON.parse(raw);
    if (Array.isArray(config.protected_files)) {
      return config.protected_files.filter((f) => typeof f === "string");
    }
  } catch (_) {
    // No config or not parseable — use defaults only
  }
  return [];
}

let data = "";
process.stdin.on("data", (chunk) => (data += chunk));
process.stdin.on("end", () => {
  try {
    const input = JSON.parse(data);
    const filePath = input.tool_input?.file_path || "";

    const repoProtected = readRepoProtectedFiles();
    const allWarn = [...new Set([...WARN_FILES, ...repoProtected])];

    const base = path.basename(filePath);
    const matches = (list) =>
      list.some(
        (p) => base === p || filePath.endsWith("/" + p) || filePath === p,
      );

    if (matches(BLOCK_FILES)) {
      process.stderr.write(
        "BLOCK: " +
          base +
          " is a generated file managed by /init. " +
          "Use the appropriate command instead of editing directly.",
      );
      process.exit(2);
    }

    if (matches(allWarn)) {
      process.stderr.write(
        "WARNING: Editing protected file " +
          base +
          ". " +
          "Ensure changes are intentional and consistent with other docs.",
      );
    }

    console.log(data);
  } catch (_) {
    // On error, allow the operation (non-blocking failure mode)
    console.log(data);
  }
});
